// Trink Fit data structure starter // Split these into: // lib/models/exercise.dart // lib/models/program.dart // lib/data/exercises_data.dart // lib/data/programs_data.dart

enum ExerciseCategory { cardio, abs, legs, arms, fullBody, hiit, stretch, }

enum LevelType { beginner, intermediate, advanced, }

enum EquipmentType { none, dumbbell, resistanceBand, gym, }

class ExerciseItem { final String id; final String name; final ExerciseCategory category; final LevelType level; final int durationSec; final int calories; final EquipmentType equipment; final String imageAsset; final String gifAsset; final String description;

const ExerciseItem({ required this.id, required this.name, required this.category, required this.level, required this.durationSec, required this.calories, required this.equipment, required this.imageAsset, required this.gifAsset, required this.description, }); }

class ProgramItem { final String id; final String title; final String group; final LevelType level; final int totalDays; final EquipmentType equipment; final bool isPremium; final List<String> exerciseIds;

const ProgramItem({ required this.id, required this.title, required this.group, required this.level, required this.totalDays, required this.equipment, required this.isPremium, required this.exerciseIds, }); }

